import { detectProject as detectProjectFromModule } from "../src/project-detector/detector";
import { loadMergedPolicy as loadMergedPolicyFromModule, type LayeredPolicy } from "../src/policy/policy-loader";
import { classifyCommand } from "../src/command-risk/classifier";
import { suggestInstalledResources } from "../src/extension-advisor/advisor";
import { validateArtifact } from "../src/artifacts/validator";
import { detectCorrectionCandidate, promoteRuleToProjectPolicy, type CandidateRule } from "../src/memory-rules/promotion";
import { createTaskState, transitionTaskState, approveWorkstream, detectDrift, type TaskStateSnapshot, type WorkstreamCategory } from "../src/task-state/state-machine";

