// INLINED PERSISTENCE LAYER — no external imports (bundler compatibility)
// ============================================================================

const CURRENT_SCHEMA = 1 as const;
const STATE_FILE = "minimax-persist.json";

interface ValidationRecord {
	cmd: string;
	lastRun: string;
	lastResult: "pass" | "fail";
	task?: string;
}
interface GrinderRecord {
	path: string;
	lastGrindSent: string;
	grindCount: number;
	lastGrindIteration: number;
}
interface PersistentAutomationState {
	schemaVersion: 1;
	validations: ValidationRecord[];
	grinds: GrinderRecord[];
	sessionChangedPaths: string[];
	sessionGrindIteration: number;
	task?: TaskStateSnapshot;
}

function isRecord(v: unknown): v is Record<string, unknown> {
	return typeof v === "object" && v !== null && !Array.isArray(v);
}
function freshState(): PersistentAutomationState {
	return { schemaVersion: CURRENT_SCHEMA, validations: [], grinds: [], sessionChangedPaths: [], sessionGrindIteration: 0, task: createTaskState() };
}
function statePath(cwd: string): string {
	return path.join(cwd, ".pi", "agent", "minimax-state", STATE_FILE);
}
function stateRoot(cwd: string): string {
	return path.join(cwd, ".pi", "agent", "minimax-state");
}
async function loadState(cwd: string): Promise<PersistentAutomationState> {
	const p = statePath(cwd);
	let raw: string;
	try { raw = fs.readFileSync(p, "utf-8"); }
	catch (err: any) { if (err?.code === "ENOENT") return freshState(); throw err; }
