	const idx = state.validations.findIndex((v) => v.cmd === record.cmd);
	if (idx >= 0) state.validations[idx] = record; else state.validations.push(record);
}
function getGrindRecord(state: PersistentAutomationState, filePath: string): GrinderRecord | undefined {
	return state.grinds.find((g) => g.path === filePath);
}
function upsertGrindRecord(state: PersistentAutomationState, rec: GrinderRecord): void {
	const idx = state.grinds.findIndex((g) => g.path === rec.path);
	if (idx >= 0) state.grinds[idx] = rec; else state.grinds.push(rec);
}
function isGrindDebounced(state: PersistentAutomationState, filePath: string, debounceWindowMs = 5 * 60 * 1000): boolean {
	const rec = getGrindRecord(state, filePath);
	if (!rec) return false;
	return Date.now() - new Date(rec.lastGrindSent).getTime() < debounceWindowMs;
}
function trackChangedPath(state: PersistentAutomationState, p: string): void {
	if (!state.sessionChangedPaths.includes(p)) state.sessionChangedPaths.push(p);
}
function nextGrindIteration(state: PersistentAutomationState): number { return ++state.sessionGrindIteration; }
function grindIterationExceeded(state: PersistentAutomationState, max: number): boolean { return state.sessionGrindIteration >= max; }
function resetSessionState(state: PersistentAutomationState): void { state.sessionChangedPaths = []; state.sessionGrindIteration = 0; }

