function readContractText(): ContractLoadResult {
	let attemptedPath = "";
	try {
		const root = getPackageRoot();
		attemptedPath = path.join(root, "docs", "AGENTS.md");
		const fileText = fs.readFileSync(attemptedPath, "utf-8").trim();
		if (fileText.length > 0) {
			return { text: fileText, source: "file" };
		}
		return {
			text: EMBEDDED_CONTRACT,
			source: "embedded",
			warning: `AGENTS.md at ${attemptedPath} is empty; using embedded contract.`,
		};
	} catch (err: any) {
		return {
			text: EMBEDDED_CONTRACT,
			source: "embedded",
			warning: attemptedPath
				? `Could not read ${attemptedPath} (${err?.code || err?.message || "error"}); using embedded contract.`
				: `Could not resolve package root for AGENTS.md (${err?.message || "error"}); using embedded contract.`,
		};
	}
}

type ProjectType =
	| "generic"
	| "node"
	| "frontend"
	| "go"
	| "wails"
	| "rust"
	| "tauri"
	| "python"
	| "php"
	| "laravel"
	| "postgres"
	| "docker";

interface DetectedProject {
	root: string;
	types: ProjectType[];
	markers: string[];
	confidence: number;
}

type PolicyDecision = "allow" | "warn" | "preflight" | "block" | "ask" | "require_approval";
type PolicyScope = "global" | "workspace" | "project" | "task";

interface PolicyRule {
	id: string;
	description?: string;
	enabled?: boolean;
	when?: {
		projectType?: string;
		tool?: string;
		commandRegex?: string;
	};
	action: PolicyDecision;
	message?: string;
}

interface LayeredPolicy {
	version: number;
	name: string;
	scope: PolicyScope;
	project?: {
		name?: string;
		root?: string;
		types?: string[];
	};
	workflow?: Record<string, unknown>;
	commandPolicy?: Record<string, string>;
	rules: PolicyRule[];
	artifactPolicy?: Record<string, unknown>;
	todoPolicy?: Record<string, unknown>;
	memoryPolicy?: Record<string, unknown>;
	extensionPolicy?: Record<string, unknown>;
}

const DEFAULT_POLICY: LayeredPolicy = {
	version: 1,
	name: "default policy",
	scope: "task",
	project: { name: "auto", root: "auto", types: ["auto"] },
	workflow: {
		requireDiagnosisBeforeEdit: false,
		requirePlanBeforeRiskyCommand: false,
		oneNextStepAfterFailure: true,
		stopOnTaskDrift: false,
		stopOnPopupError: false,
		stopOnEmptyOutput: false,
		stopOnArtifactMismatch: false,
	},
	commandPolicy: {
		safeRead: "allow",
		build: "preflight",
		install: "require_reason",
		destructive: "require_approval",
		deploy: "require_explicit_user_request",
		database: "require_backup_or_dry_run",
		network: "require_reason",
		unknown: "ask",
	},
	rules: [],
	artifactPolicy: {
		verifyOutputExists: false,
		verifyOutputTimestamp: false,
		verifyHashWhenCopyingArtifacts: false,
		verifyNonEmptyOutputDir: false,
	},
	todoPolicy: {
		maxActiveTodos: 3,
		blockUnrelatedTodos: false,
		requireUserApprovalForNewWorkstream: false,
	},
	memoryPolicy: {
		detectCorrections: false,
		proposeRulePromotion: false,
		autoPromote: false,
		storeCandidateRules: false,
	},
	extensionPolicy: {
		preferInstalledExtensions: true,
		requireAuditBeforeNewExtension: false,
	},
};

function detectProject(cwd: string): DetectedProject {
	const detected = detectProjectFromModule(cwd);
	return {
		root: detected.root,
		types: detected.types as ProjectType[],
		markers: detected.evidenceFiles,
		confidence: detected.confidence,
	};
}

function loadMergedPolicy(cwd: string, project: DetectedProject, taskPolicy?: Partial<LayeredPolicy>): LayeredPolicy {
	return loadMergedPolicyFromModule(cwd, {
		root: project.root,
		types: project.types as any,
		confidence: project.confidence,
		evidenceFiles: project.markers,
		recommendedProfiles: project.types.filter((t) => t !== "generic") as string[],
	}, taskPolicy || null).merged;
}

// ============================================================================
// TOOL OP TRACKING (in-memory per-request)
// ============================================================================

type ToolOp = { toolName: string; path?: string; editsPaths?: string[]; index: number; command?: string; isError?: boolean; evidence?: string; hint?: string };
type TurnToolState = { ops: ToolOp[] };

function asPath(v: any): string | undefined { return typeof v === "string" ? v : undefined; }
function unique<T>(items: T[]): T[] { return [...new Set(items)]; }
function isValidationLikeCommand(cmd: string): boolean {
	return /\b(tsc|eslint|vitest|jest|pytest|cargo test|go test|npm test|npm run (test|build|lint|typecheck)|pnpm (test|build|lint)|yarn (test|build|lint)|bun test)\b/i.test(cmd);
}
function extractToolResultText(result: any): string {
	if (!result) return "";
	if (typeof result === "string") return result;
	const parts: string[] = [];
	if (typeof result.stdout === "string") parts.push(result.stdout);
	if (typeof result.stderr === "string") parts.push(result.stderr);
	if (typeof result.output === "string") parts.push(result.output);
	if (Array.isArray(result.content)) {
		for (const item of result.content) if (item && typeof item.text === "string") parts.push(item.text);
	}
	return parts.join("\n").trim();
}
function firstFailureLine(text: string): string {
	const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
	return lines.find((l) => /\berror\b|failed|exception|traceback|cannot find|not assignable|does not exist/i.test(l)) || lines[0] || "verification command failed";
}
function hintForFailure(evidence: string): string {
	if (/TS2322|not assignable to type/i.test(evidence)) return "Type mismatch: align the declared type with the assigned value, or convert the value before assignment.";
	if (/TS2304|Cannot find name/i.test(evidence)) return "Missing symbol: define it, import it, or correct the identifier spelling/scope.";
	if (/TS2339|Property .* does not exist/i.test(evidence)) return "Invalid property access: update the object type or use an existing property.";
	if (/Cannot find module|module not found/i.test(evidence)) return "Module resolution issue: check install status, import path, and tsconfig/module settings.";
	if (/command not found|not recognized as an internal or external command/i.test(evidence)) return "Missing command: verify the tool is installed and available on PATH, or use the nearest documented repo command.";
	if (/ENOENT|no such file or directory/i.test(evidence)) return "Missing path: verify the file or directory exists before rerunning the command.";
	if (/EACCES|permission denied|access is denied/i.test(evidence)) return "Permission issue: check file ownership, locks, and whether the command needs a different writable location.";
	if (/EADDRINUSE|address already in use/i.test(evidence)) return "Port conflict: stop the existing process or choose a free port before rerunning.";
	if (/AssertionError|expected .* to/i.test(evidence)) return "Test assertion failed: inspect the expected versus actual values, then fix the smallest behavior mismatch.";
	if (/detached HEAD|working tree|uncommitted changes/i.test(evidence)) return "Git state issue: inspect status, preserve local changes, then retry the git operation from a clean state.";
	if (/syntax|unexpected token/i.test(evidence)) return "Syntax issue: inspect the reported line/column and fix the malformed expression or delimiter.";
	return "Read the first failure line, make one minimal fix, then rerun the same verification command.";
}
function appendTextToMessage(message: any, text: string): any {
	if (typeof message.content === "string") return { ...message, content: message.content + text };
	if (Array.isArray(message.content)) return { ...message, content: [...message.content, { type: "text", text }] };
	return { ...message, content: String(message.content || "") + text };
}

